from vendor_v1 import add_tax

def invoice(cents):
    return add_tax(cents)

import unittest
from invoice import invoice

class InvoiceTests(unittest.TestCase):
    def test_public_amounts(self):
        for cents in (0, 1, 100, 12500):
            with self.subTest(cents=cents):
                self.assertEqual(invoice(cents), cents + 5)
